import{_ as t}from"./chunks/relationship.DaNqy3l1.js";import{_ as a,o,c as s,a1 as r}from"./chunks/framework.DH-rCavj.js";const f=JSON.parse('{"title":"Projects","description":"","frontmatter":{},"headers":[],"relativePath":"reference/essentials/projects.md","filePath":"reference/essentials/projects.md","lastUpdated":1737491561000}'),i={name:"reference/essentials/projects.md"};function n(l,e,c,d,p,h){return o(),s("div",null,e[0]||(e[0]=[r('<h1 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h1><p>OpenCUI is a conversational user interface (CUI) platform that allows builders, including designers and developers, to create, test, and manage CUI components or applications, commonly referred to as chatbots, agents, assistants, or copilots. The CUI development on OpenCUI are structured as projects, which may include chatbots, modules, providers, and knowledge bases. The diagram below illustrates how these components typically interact to provide a smooth conversational experience.</p><p><img src="'+t+'" alt="relationship"></p><h3 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to &quot;Modules&quot;">​</a></h3><p>Modules are reusable conversational components. For example, a CUI date picker is a simple module that gets the user&#39;s preferred date. Modules can be combined to form larger modules for more complex use cases, or they can be imported into the chatbot to add new conversational functionalities.</p><p>A module usually defined on top of a service (not always). A service is simply an interface erepresents a capability, typically exposed as a set of API functions. Services (also known as interface) decouple the CUI from the actual capability provider (or implementation).</p><h3 id="providers" tabindex="-1">Providers <a class="header-anchor" href="#providers" aria-label="Permalink to &quot;Providers&quot;">​</a></h3><p>A service can have one or more providers that link the chatbot to its backend implementation, enabling it to perform its functions. Providers can be shared across different chatbots within the same organization, promoting reusability. Thanks to OpenCUI&#39;s open architecture design, it supports a variety of provider types. Some examples include:</p><ol><li>PostgreSQL (OpenCUI-hosted): A relational database provider for managing structured data.</li><li>RESTful Providers: For connecting to web services and APIs using the REST architecture.</li><li>Native Providers: Allowing for integration with backend systems using kotlin code.</li></ol><h3 id="chatbots" tabindex="-1">Chatbots <a class="header-anchor" href="#chatbots" aria-label="Permalink to &quot;Chatbots&quot;">​</a></h3><p>A chatbot is an application that delivers services to users through a conversational user interface (CUI), it is also known as agents, copilots, assistant etc. Chatbots, or CUI applications, are typically rely on imported modules for the CUI capabilities, so that builder does not need to start from scratch.</p><h3 id="knowledge" tabindex="-1">Knowledge <a class="header-anchor" href="#knowledge" aria-label="Permalink to &quot;Knowledge&quot;">​</a></h3><p>Not every thing is stored in the structured representation, like APIs or databases. Sometime, useful information can be stored in unstrcutured format. Knowledge is simply a collection of articles or documents that the system can reference to answer user queries. The knowledge base can be populated with structured information that the agent can search to provide responses. These information can be surfaced to users using RAG system.</p>',13)]))}const b=a(i,[["render",n]]);export{f as __pageData,b as default};
